  // 100%制覇した都道府県の一覧(特別表示用)
  const completedPrefs = Object.keys(prefGroups).filter(p => {
    const g = prefGroups[p];
    return g.total > 0 && g.done >= g.total;
  });
  // 完全制覇した地方の一覧(お祝い演出用)
  const completedRegions = REGION_ORDER.filter(r => ctx.regionFullyConquered(r));

