function v371SurpriseOwnerMatches(key, city){
 const os=V378_SURPRISE_OWNERS[key]; if(!os||!os.length) return true;
 return !!city && os.includes(v371CityOwnerId(city));
}
function v371CanFireSurpriseFor(key, city){
 const os=V378_SURPRISE_OWNERS[key]; if(!os||!os.length) return true;
 return !!city && os.includes(v371CityOwnerId(city));
}
const V381_OWNER_FACES=R89_DERIVED.faces;
const V381_OWNER_STRIKES=R89_DERIVED.strikes;
let v385SharedFaceYesAt=-1;
