 if(!city) return null;
 const oid=v371CityOwnerId(city);
 const ss=(V381_OWNER_STRIKES[oid]||[]).filter(k=>!asked.includes(k)&&city.tags[k]===true&&v371CanFireSurpriseFor(k,city));
 const fs=(V381_OWNER_FACES[oid]||[]).filter(k=>!asked.includes(k)&&city.tags[k]===true&&!ss.includes(k));
 if(!ss.length||!fs.length) return null;
