function cp50AxisOf(k){
  if(!k) return 'other';
  if(isPrefQuestion(k)||REGION_QUESTION_KEYS.has(k)||CP44_SUBREGION_PARENT_PREF[k]) return 'geography';
  if(CP96_AUDITED_EVIDENCE_AXIS[k]) return CP96_AUDITED_EVIDENCE_AXIS[k];
  const cat=categoryOf(k)||'';
  // CP96: semantic category first. Never infer nature/transport from a single character inside a proper noun.
  if(/買い物|外食|商業/.test(cat)) return 'commerce';
  if(/学校|教育/.test(cat)) return 'education';
  if(/行政|公共/.test(cat)) return 'civic';
  if(/交通|鉄道/.test(cat)) return 'transport';
  if(/自然|地理/.test(cat)) return 'nature';
  if(/産業/.test(cat)) return 'industry';
  if(/文化|歴史|観光|祭|食|スポーツ|学問|遊び心/.test(cat)) return 'culture';
  if(/人口|都市|町村|区|政令/.test(cat)) return 'urbanity';
  if(r90IsNamePlayKey(k)) return 'name';
  // Fallback is restricted to unambiguous structural phrases, not 山/川/海/港/駅 characters.
  const text=QUESTIONS[k]?.text||'';
  if(/新幹線|地下鉄|高速道路|空港/.test(text)) return 'transport';
  if(/人口|政令指定都市/.test(text)) return 'urbanity';
  return 'other';
}
function cp50EvidenceForCity(city){
  const support=[],against=[]; const axisSupport={};
  for(const a of answerLog){
    if(!a||a.val===null||!QUESTIONS[a.key]) continue;
    const match=(city.tags[a.key]===true)===(a.val===true);
    const row={key:a.key,answer:a.val===true?'YES':'NO',axis:cp50AxisOf(a.key),role:a.role||'general'};
    (match?support:against).push(row);
    if(match) axisSupport[row.axis]=(axisSupport[row.axis]||0)+1;
  }
  return {support:support.slice(-8),against:against.slice(-5),axisSupport};
}
function cp50ShadowQuestion(hyps,live,intentType){
  if(!hyps||hyps.length<2||!live.cities.length) return null;
  const recentAxes=answerLog.slice(-3).map(a=>cp50AxisOf(a&&a.key));
  const masses=posteriorMassForCities(live.cities);
  const frontier=[];
  for(const k of activeKeysForMode(currentMode)){
    if(r89Shown(k)||!QUESTIONS[k]||isSubjectiveQuestion(k)) continue;
    if(cp45IsAddressQuestion(k)||r89IsLaneOnlyKey(k)||v330IsTownFaceCandidate(k)||v330IsDedicatedSurpriseStrike(k)) continue;
    if(!r90NamePlayAllowedNow(k)||!v330LocalChainContextAllowed(k,live.cities)) continue;
    let yes=0; for(const c of live.cities) if(c.tags[k]===true) yes++;
    if(yes<=1||yes>=live.cities.length-1) continue;
    let disagreements=0,weighted=0;
    for(let i=0;i<hyps.length;i++) for(let j=i+1;j<hyps.length;j++){
      if(hyps[i].city.tags[k]===hyps[j].city.tags[k]) continue;
      disagreements+=(hyps[i].confidence+hyps[j].confidence); weighted++;
    }
    if(!weighted) continue;
    const gain=questionInformationGain(live.cities,masses,k); if(!Number.isFinite(gain)||gain<=0) continue;
    const axis=cp50AxisOf(k), ratio=yes/live.cities.length;
    const leadYes=hyps[0].city.tags[k]===true, secondYes=hyps[1].city.tags[k]===true;
    let score=gain*100+disagreements*42-Math.abs(.5-ratio)*8;
    if(!recentAxes.includes(axis)) score+=8; else score-=6;
    if(axis!=='other') score+=4;
    const gy=v170GlobalYesCount(k); if(gy>=5&&gy<=180) score+=5;
    // Intent is decided first; the ball should serve that thought, not merely have high entropy.
    if(intentType==='confirm' && leadYes) score+=13;
    if(intentType==='challenge' && leadYes!==secondYes) score+=15;
    if(intentType==='pivot' && !leadYes && secondYes) score+=15;
    if(intentType==='converge' && leadYes!==secondYes) score+=18;
    frontier.push({key:k,axis,score:Number(score.toFixed(3)),gain:Number(gain.toFixed(4)),yes,live:live.cities.length,leadYes,secondYes});
  }
  frontier.sort((a,b)=>b.score-a.score);
  if(!frontier.length) return null;
  // CP50 Stage 3 SHADOW: controlled human-like route diversity.
  // Never roulette across arbitrary categories: only choose among near-best balls that serve
  // the already-decided hypothesis intent.  Audit runs seed Math.random per target/run, so the
  // same municipality can explore reproducible alternate coherent routes.
  const bestScore=frontier[0].score;
  const near=frontier.slice(0,5).filter(x=>x.score>=bestScore-Math.max(4.5,Math.abs(bestScore)*0.035));
  const recentAxesSet=new Set(recentAxes);
  const coherent=near.filter(x=>!recentAxesSet.has(x.axis));
  const pool=(coherent.length>=2?coherent:near).slice(0,3);
  let chosen=pool[0];
  if(pool.length>1){
    const floor=Math.min(...pool.map(x=>x.score));
    const weights=pool.map((x,i)=>Math.max(1,(x.score-floor)+3)/(1+i*.10));
    let r=Math.random()*weights.reduce((a,b)=>a+b,0);
    for(let i=0;i<pool.length;i++){ r-=weights[i]; if(r<=0){chosen=pool[i];break;} }
  }
  chosen.frontier=frontier.slice(0,3).map(x=>({key:x.key,axis:x.axis,score:x.score,leadYes:x.leadYes,secondYes:x.secondYes}));
  chosen.diversity={mode:'coherent-near-best',pool:pool.map(x=>x.key),bestKey:frontier[0].key,bestScore,chosenRank:frontier.indexOf(chosen)+1};
  return chosen;
}
function cp50IntentFor(hyps,live){
  if(!hyps||hyps.length<2) return null;
  const a=hyps[0],b=hyps[1];
  const recent=answerLog.slice(-4);
  const recentNo=recent.filter(x=>x&&x.val===false).length;
  const aAgainst=(a.against||[]).length, aAxes=Object.keys(a.axisSupport||{}).filter(k=>(a.axisSupport[k]||0)>0).length;
  const gap=(a.confidence||0)-(b.confidence||0);
  let type='challenge', reason='上位2仮説を別角度の証拠で比較する';
  if((a.confidence||0)>=0.56 && gap>=0.18 && aAxes>=2){type='converge';reason='複数軸の証拠が首位仮説へ収束。最後の別角度確認を探す';}
  else if(aAgainst>=2 || recentNo>=3){type='pivot';reason='首位仮説への反証が増加。次点仮説へ視線を移せる球を探す';}
  else if((a.confidence||0)>=0.38 && aAxes>=2){type='confirm';reason='首位仮説を支持する独立した証拠をもう一つ確認する';}
  return {type,between:[a.name,b.name],reason,confidenceGap:Number(gap.toFixed(4)),leadAxes:aAxes,liveCount:live.trueCount};
}
function cp50RefreshShadow(){
  if(currentMode!=='all'){cp50ShadowState={hypotheses:[],intent:null,suggestedKey:null,updatedAt:answerLog.length};return cp50ShadowState;}
  const live=r89Live();
  const ranked=sortedPool().filter(e=>e&&e.city&&!excludedNames.has(e.city.name)).slice(0,5);
  if(!ranked.length){cp50ShadowState={hypotheses:[],intent:null,suggestedKey:null,updatedAt:answerLog.length};return cp50ShadowState;}
  const probs=candidateProbabilities(ranked); let total=probs.reduce((a,b)=>a+b,0)||1;
  const hyps=ranked.map((e,i)=>{
    const ev=cp50EvidenceForCity(e.city);
    return {city:e.city,name:e.city.name,pref:e.city.pref,confidence:Number(((probs[i]||0)/total).toFixed(4)),support:ev.support,against:ev.against,axisSupport:ev.axisSupport};
  });
  const intent=cp50IntentFor(hyps,live);
  const q=cp50ShadowQuestion(hyps,live,intent&&intent.type);
  if(intent) intent.preferredAxis=q?q.axis:'other';
  const assetDecision=cp53AssetSnapshot(hyps,intent);
  cp50ShadowState={hypotheses:hyps.map(({city,...x})=>x),intent,suggestedKey:q&&q.key||null,suggestion:q,assetDecision,updatedAt:answerLog.length,liveCount:live.trueCount};
  return cp50ShadowState;
}
// CP74 SHADOW: Thought Candidate Generator ("あそこかも" layer).
// The old CP50 hunch waited for one posterior leader to become strong. Humans do not:
// they keep a small mental shortlist and notice a place that repeatedly stays plausible from
// several independent town features.  CP74 therefore tracks persistence/rank/axes BEFORE certainty.
// Audit-only: it cannot select a live question in CP74.
let cp74ThoughtMemory={};
function cp74ResetThoughtMemory(){ cp74ThoughtMemory={}; }
function cp74ThoughtCandidates(){
  if(currentMode!=='all'||answerLog.length<5){ if(answerLog.length===0) cp74ResetThoughtMemory(); return []; }
  const ranked=sortedPool().filter(e=>e&&e.city&&!excludedNames.has(e.city.name)).slice(0,12);
  if(!ranked.length) return [];
  const probs=candidateProbabilities(ranked), now=answerLog.length, out=[];
  for(let i=0;i<ranked.length;i++){
    const city=ranked[i].city, owner=city.pref+'::'+city.name, ev=cp50EvidenceForCity(city);
    const axes=Object.keys(ev.axisSupport||{}).filter(a=>a!=='other'&&(ev.axisSupport[a]||0)>0);
    const support=ev.support.filter(x=>x.axis!=='other');
    const vivid=support.filter(x=>!cp45IsAddressQuestion(x.key));
    const old=cp74ThoughtMemory[owner]||{seen:0,lastAt:-99,bestRank:99,streak:0};
    // CP77: reading a thought snapshot twice in one turn must not mutate its persistence.
    const sameTurn=old.lastAt===now;
    const contiguous=old.lastAt===now-1;
    const streak=sameTurn?old.streak:(contiguous?old.streak+1:1);
    const seen=sameTurn?old.seen:old.seen+1;
    cp74ThoughtMemory[owner]={seen,lastAt:now,bestRank:Math.min(old.bestRank,i+1),streak};
    // A thought may be born before a confident leader, but not from geography alone.
    // Persistence + two non-address evidence axes is the human "this place keeps coming back to mind" signal.
    const nonGeoAxes=axes.filter(a=>a!=='geography');
    const strongAsset=(CP53_ASSET_HANDS[owner]||[]).some(a=>['S','A'].includes(a.l)&&!r89Shown(a.k));
    let thoughtScore=(12-i)*2 + Math.min(5,streak)*5 + Math.min(4,nonGeoAxes.length)*7 + Math.min(4,vivid.length)*2 + (strongAsset?3:0) + (probs[i]||0)*20;
    const stage=(streak>=3&&nonGeoAxes.length>=2&&i<5)?'hunch':(streak>=2&&nonGeoAxes.length>=1&&i<8)?'glimpse':'candidate';
    out.push({owner,name:city.name,pref:city.pref,rank:i+1,posterior:Number((probs[i]||0).toFixed(4)),streak,axes,nonGeoAxes,vividKeys:vivid.slice(-4).map(x=>x.key),strongAsset,stage,thoughtScore:Number(thoughtScore.toFixed(2))});
  }
  // Forget stale thoughts instead of carrying them forever.
  for(const k of Object.keys(cp74ThoughtMemory)) if(now-cp74ThoughtMemory[k].lastAt>3) delete cp74ThoughtMemory[k];
  return out.sort((a,b)=>b.thoughtScore-a.thoughtScore).slice(0,5);
}
function cp74ThoughtSnapshot(){
  const rows=cp74ThoughtCandidates();
  return {primary:rows.find(x=>x.stage==='hunch')||rows.find(x=>x.stage==='glimpse')||null,shortlist:rows};
}

// CP75 LIVE: Thought Verification for all municipalities.
// When a persistent, multi-axis CP74 hunch exists, do not forget it and restart generic search.
// Ask one natural, non-address, non-unique question that separates the hunch from a live rival,
// while preserving most of the best available information value. This is a verification beat,
// not a finisher and not a municipality-specific patch.
let cp75ShowcaseUsedOwners=new Set(), cp75PendingShowcaseOwner=null;
function cp75PickThoughtVerification(baseKey){
  if(currentMode!=='all'||!['normal','extra'].includes(questionPhase)||answerLog.length<7||!baseKey) return null;
  const thought=cp74ThoughtSnapshot(), shortlist=(thought&&thought.shortlist||[]).filter(x=>x.streak>=2).slice(0,5);
  if(shortlist.length<2) return null;
  const live=r89Live(); if(!live.cities||live.cities.length<5) return null;
  const masses=posteriorMassForCities(live.cities);
  const baseGain=questionInformationGain(live.cities,masses,baseKey);
  if(!Number.isFinite(baseGain)||baseGain<=0) return null;
  const cityByOwner=new Map(); for(const e of sortedPool()) if(e&&e.city) cityByOwner.set(e.city.pref+'::'+e.city.name,e.city);
  const thoughts=shortlist.map(t=>({t,city:cityByOwner.get(t.owner)})).filter(x=>x.city);
  if(thoughts.length<2) return null;
  const leadThought=thoughts[0], leadOwner=leadThought.t.owner;
  const showcaseLead=!!(leadThought.city.tags.designated||leadThought.city.tags.is_tokyo_ward||leadThought.city.tags.prefectural_capital);
  if(showcaseLead && cp75ShowcaseUsedOwners.has(leadOwner)) return null;
  const recentAxes=new Set(answerLog.slice(-3).map(a=>cp50AxisOf(a&&a.key)));
  const rows=[];
  for(const k of activeKeysForMode(currentMode)){
    if(k===baseKey||r89Shown(k)||!QUESTIONS[k]||isSubjectiveQuestion(k)) continue;
    if(cp45IsAddressQuestion(k)||r89IsLaneOnlyKey(k)||v330IsTownFaceCandidate(k)||v330IsDedicatedSurpriseStrike(k)) continue;
    if(!r90NamePlayAllowedNow(k)||!v330LocalChainContextAllowed(k,live.cities)) continue;
    let yes=0; for(const c of live.cities) if(c.tags[k]===true) yes++;
    if(yes<=1||yes>=live.cities.length-1) continue;
    const gain=questionInformationGain(live.cities,masses,k); if(!Number.isFinite(gain)||gain<baseGain*.995) continue;
    const axis=cp50AxisOf(k); if(axis==='geography'||axis==='other'||recentAxes.has(axis)) continue;
    let disagreement=0;
    for(let i=0;i<thoughts.length;i++) for(let j=i+1;j<thoughts.length;j++){
      if(thoughts[i].city.tags[k]!==thoughts[j].city.tags[k]) disagreement += (thoughts[i].t.thoughtScore+thoughts[j].t.thoughtScore)/100;
    }
    if(disagreement<=0) continue;
    const gy=v170GlobalYesCount(k);
    let score=gain*100+disagreement*18+(gy>=5&&gy<=180?5:0);
    rows.push({key:k,gain,score,axis,disagreement});
  }
  if(!rows.length) return null;
  rows.sort((a,b)=>b.score-a.score);
  // Replace only when the shortlist question is at least as discriminating as the ordinary ball,
  // or is essentially tied and materially better at testing the thoughts already in mind.
  const best=rows[0];
  if(best.gain+1e-9 < baseGain*.995) return null;
  cp75PendingShowcaseOwner=showcaseLead?leadOwner:null;
  return best.key;
}

// CP73 SHADOW: Persistent Hunch Memory.
// Unlike the per-turn ranking, this state deliberately remembers a plausible thought across turns.
// It is audit-only in CP73: it cannot choose a live question yet.
let cp73HunchMemory={owner:null,name:null,pref:null,bornAt:-1,lastAt:-1,strength:0,status:'none',axes:[],supportKeys:[],againstKeys:[],runnerUp:null,history:[]};
function cp73ResetHunchMemory(){ cp73HunchMemory={owner:null,name:null,pref:null,bornAt:-1,lastAt:-1,strength:0,status:'none',axes:[],supportKeys:[],againstKeys:[],runnerUp:null,history:[]}; }
function cp73RefreshHunchMemory(st){
  if(currentMode!=='all'||answerLog.length===0){ if(answerLog.length===0) cp73ResetHunchMemory(); return cp73HunchMemory; }
  if(cp73HunchMemory.lastAt>answerLog.length) cp73ResetHunchMemory();
  const hs=st&&st.hypotheses||[]; if(hs.length<2) return cp73HunchMemory;
  const lead=hs[0], second=hs[1], owner=lead.pref+'::'+lead.name;
  const axes=Object.entries(lead.axisSupport||{}).filter(([a,n])=>a!=='other'&&n>0).map(([a])=>a);
  const support=(lead.support||[]).map(x=>x.key), against=(lead.against||[]).map(x=>x.key);
  const gap=(lead.confidence||0)-(second.confidence||0);
  const birthReady=answerLog.length>=5&&axes.length>=2&&(lead.confidence||0)>=.10&&gap>=.015;
  const snap=(event)=>({at:answerLog.length,event,lead:lead.name,runnerUp:second.name,confidence:lead.confidence,gap:Number(gap.toFixed(4)),axes:[...axes]});
  if(!cp73HunchMemory.owner){
    if(birthReady) cp73HunchMemory={owner,name:lead.name,pref:lead.pref,bornAt:answerLog.length,lastAt:answerLog.length,strength:1,status:'forming',axes,supportKeys:support,againstKeys:against,runnerUp:second.name,history:[snap('born')]};
    return cp73HunchMemory;
  }
  if(cp73HunchMemory.owner===owner){
    const newAxis=axes.some(a=>!cp73HunchMemory.axes.includes(a));
    const newSupport=support.some(k=>!cp73HunchMemory.supportKeys.includes(k));
    cp73HunchMemory.strength=Math.min(6,cp73HunchMemory.strength+(newAxis?1.1:0)+(newSupport?.45:0)+(gap>=.08?.25:0));
    cp73HunchMemory.axes=axes; cp73HunchMemory.supportKeys=support; cp73HunchMemory.againstKeys=against; cp73HunchMemory.runnerUp=second.name; cp73HunchMemory.lastAt=answerLog.length;
    cp73HunchMemory.status=(cp73HunchMemory.strength>=2&&axes.length>=3)?'aha-ready':'forming';
    cp73HunchMemory.history.push(snap(newAxis?'strengthened-axis':newSupport?'strengthened':'held'));
  } else {
    const old=hs.find(h=>(h.pref+'::'+h.name)===cp73HunchMemory.owner);
    const oldPlausible=old&&(old.confidence||0)>=Math.max(.06,(lead.confidence||0)*.60)&&(old.against||[]).length<=3;
    if(oldPlausible){
      cp73HunchMemory.strength=Math.max(.4,cp73HunchMemory.strength-.35); cp73HunchMemory.status='challenged'; cp73HunchMemory.lastAt=answerLog.length; cp73HunchMemory.runnerUp=lead.name; cp73HunchMemory.history.push(snap('remembered-despite-rank-swap'));
    } else if(birthReady){
      const oldHist=cp73HunchMemory.history.slice(-8); cp73HunchMemory={owner,name:lead.name,pref:lead.pref,bornAt:answerLog.length,lastAt:answerLog.length,strength:1,status:'forming',axes,supportKeys:support,againstKeys:against,runnerUp:second.name,history:oldHist.concat(snap('pivot'))};
    } else { cp73HunchMemory.history.push(snap('dropped')); cp73ResetHunchMemory(); }
  }
  if(cp73HunchMemory.history.length>12) cp73HunchMemory.history=cp73HunchMemory.history.slice(-12);
  return cp73HunchMemory;
}
function cp73HunchSnapshot(st){ const h=cp73RefreshHunchMemory(st); return {owner:h.owner,name:h.name,pref:h.pref,bornAt:h.bornAt,lastAt:h.lastAt,strength:Number((h.strength||0).toFixed(2)),status:h.status,axes:h.axes,runnerUp:h.runnerUp,history:(h.history||[]).slice(-5)}; }

function cp50ShadowSnapshot(){
  const st=cp50RefreshShadow();
  return {liveCount:st.liveCount,hypotheses:(st.hypotheses||[]).map(h=>({name:h.name,pref:h.pref,confidence:h.confidence,support:h.support.slice(-4),against:h.against.slice(-3),axisSupport:h.axisSupport})),intent:st.intent,suggestedKey:st.suggestedKey,suggestion:st.suggestion||null,assetDecision:st.assetDecision||null,hunch:cp73HunchSnapshot(st),thought:cp74ThoughtSnapshot()};
}

